import re
import string
import gensim
from bs4 import BeautifulSoup


class HtmlUtil:

    SPACE_MARK = '-SPACE-'
    JSON_MARK = '-JSON-'
    MARKUP_LANGUAGE_MARK = '-MARKUP_LANGUAGE-'
    URL_MARK = '-URL-'
    NUMBER_MARK = '-NUMBER-'
    TRACE_MARK = '-TRACE-'
    COMMAND_MARK = '-COMMAND-'
    COMMENT_MARK = '-COMMENT-'
    CODE_MARK = '-CODE-'

    def __init__(self):
        pass

    @staticmethod
    def __format_line_feed(text):
        return re.sub(re.compile(r'\n+'), '\n', text)

    @staticmethod
    def _is_empty(text):
        return text is None or len(text) == 0

    @staticmethod
    def _has_punctuation_ending(text):
        return len(text) > 0 and text[-1] in string.punctuation

    def _process_ul_ol_tags(self, soup):
        ul_ol_group = soup.find_all(name=['ul', 'ol'])
        for ul_ol_item in ul_ol_group:
            self._process_li_items(ul_ol_item)

    def _process_li_items(self, ul_ol_item):
        li_group = ul_ol_item.find_all('li')
        for li_item in li_group:
            self._process_li_item_text(li_item)

    def _process_li_item_text(self, li_item):
        li_item_text = li_item.get_text().strip()
        if len(li_item_text) == 0:
            return
        if self._has_punctuation_ending(li_item_text):
            li_item.string = '[{0}]{1}'.format('-', li_item_text)
        else:
            li_item.string = '[{0}]{1}.'.format('-', li_item_text)

    def _process_p_tags(self, soup):
        p_group = soup.find_all(name=['p'])
        for p_item in p_group:
            self._process_p_item_text(p_item)

    def _process_p_item_text(self, p_item):
        p_item_text = p_item.get_text().strip()
        if not p_item_text:
            return
        if self._has_punctuation_ending(p_item_text):
            p_item.string = p_item_text
        else:
            self._process_p_without_punctuation(p_item, p_item_text)

    def _process_p_without_punctuation(self, p_item, p_item_text):
        next_sibling = p_item.find_next_sibling()
        if next_sibling and self.CODE_MARK in next_sibling.get_text():
            p_item.string = p_item_text + ':'
        else:
            p_item.string = p_item_text + '.'

    def _process_code_tags(self, soup):
        code_tag = soup.find_all(name=['pre', 'blockquote'])
        for tag in code_tag:
            tag.string = self.CODE_MARK

    def format_line_html_text(self, html_text):
        if self._is_empty(html_text):
            return ''
        soup = BeautifulSoup(html_text, 'lxml')

        self._process_code_tags(soup)
        self._process_ul_ol_tags(soup)
        self._process_p_tags(soup)

        clean_text = gensim.utils.decode_htmlentities(soup.get_text())
        return self.__format_line_feed(clean_text)

    @staticmethod
    def _has_code_mark(text):
        return HtmlUtil.CODE_MARK in text

    def _gather_code_texts(self, code_tag, code_list, code_count):
        for code_index in range(code_count):
            code = code_tag[code_index].get_text()
            if code:
                code_list.append(code)

    def extract_code_from_html_text(self, html_text):
        text_with_code_tag = self.format_line_html_text(html_text)

        if not self._has_code_mark(text_with_code_tag):
            return []

        soup = BeautifulSoup(html_text, 'lxml')
        code_tag = soup.find_all(name=['pre', 'blockquote'])
        code_count = text_with_code_tag.count(self.CODE_MARK)
        code_list = []
        self._gather_code_texts(code_tag, code_list, code_count)
        return code_list
